for row in [
 ('TURN45_MS','Поворот на 45° без разгона',510,50,3000),('TURN45_LOADED_MS','45° с грузом без разгона',579,50,3500),('TURN_START_MS','Поправка на разгон поворота',55,0,1000),('TURN_RIGHT_SCALE','Поправка правого поворота /1000',1000,500,1500),('UTURN_MIN_MS','Начало поиска линии после разворота',2050,100,10000),('UTURN_MAX_MS','Тайм-аут разворота',2550,200,15000),('UTURN_LOADED_MIN_MS','Поиск линии после разворота с грузом',2320,100,12000),('UTURN_LOADED_MAX_MS','Тайм-аут разворота с грузом',2900,200,15000),('TURN_LINE_MS','Подтверждение линии после разворота',30,5,200),('SETTLE_MS','Пауза после остановки',120,0,1000),('HUB_EXIT_MS','Выезд из круга до поиска линии',650,50,5000),('ACQUIRE_MS','Тайм-аут захвата линии',1800,100,8000),('CENTRE_LEFT_MS','До центра левого круга',1650,0,6000),('CENTRE_RIGHT_MS','До центра правого круга',1650,0,6000),('BRIDGE_MIN_MS','Минимум до второго круга',2000,0,20000),('BRIDGE_MAX_MS','Тайм-аут перемычки',15000,1000,60000),('BRIDGE_ENTRY_MS','Вход во второй круг по времени',9000,1000,50000),('REVERSE_RATIO','Компенсация отхода после поиска /1000',1000,200,3000),('MISSION_SECONDS','Общий тайм-аут задания',240,30,1800)]:p(*row,'Навигация','мс' if row[0].endswith('MS') else '')
