zones=[dict(key=k,label=l,default=d,min=lo,max=hi) for k,l,d,lo,hi in [
 ('OUT_MIN_MS','Не учитывать отметки в начале луча',500,0,5000),('OUT_MAX_MS','Тайм-аут движения к зоне',7500,500,30000),('SEARCH_MS','Поиск груза после Т-отметки',850,0,5000),('BACKOFF_MS','Отход перед разворотом',800,0,5000),('RETURN_MIN_MS','Минимум до своего круга',350,0,5000),('RETURN_MAX_MS','Тайм-аут возврата',7500,500,30000),('RETURN_ENTRY_MS','Вход в круг по времени',1800,0,20000),('DROP_ADVANCE_MS','Движение после отметки до разгрузки',0,0,4000),('DROP_BACK_MS','Отход после разгрузки',1300,100,6000)]]
names={x['key']:i for i,x in enumerate(params)};s=['#pragma once','#include <stdint.h>','enum Param {']+[' P_'+x['key']+'='+str(i)+',' for i,x in enumerate(params)]+[' P_COUNT};','enum ZoneParam {']+[' Z_'+x['key']+'='+str(i)+',' for i,x in enumerate(zones)]+[' Z_COUNT};','struct Settings { uint16_t v[P_COUNT]; uint16_t zone[2][8][Z_COUNT]; uint8_t search[7]; uint8_t searchCount; };','inline uint8_t bridgeRay(uint8_t hub){return hub?4:0;}','inline int settingsError(const Settings &s){']
for i,x in enumerate(params):s.append(f' if(s.v[{i}]<{x["min"]} || s.v[{i}]>{x["max"]})return {i+1};')
s += [' if(s.v[P_LINE_THRESHOLD]>=s.v[P_WIDE_THRESHOLD])return 200;',' if(s.v[P_UTURN_MIN_MS]>=s.v[P_UTURN_MAX_MS] || s.v[P_UTURN_LOADED_MIN_MS]>=s.v[P_UTURN_LOADED_MAX_MS])return 201;',' if(s.v[P_DROP_RAY]==bridgeRay(1-s.v[P_START_HUB]))return 202;',' if(s.searchCount<1 || s.searchCount>7)return 203;',' uint8_t seen=0; for(uint8_t i=0;i<s.searchCount;i++){uint8_t r=s.search[i];if(r>7 || r==bridgeRay(s.v[P_START_HUB]) || (seen&(1U<<r)))return 204;seen|=1U<<r;}',' for(uint8_t h=0;h<2;h++)for(uint8_t r=0;r<8;r++){']
for i,x in enumerate(zones):s.append(f' if(s.zone[h][r][{i}]<{x["min"]} || s.zone[h][r][{i}]>{x["max"]})return {210+i};')
s+=[' if(s.zone[h][r][Z_OUT_MIN_MS]>=s.zone[h][r][Z_OUT_MAX_MS] || s.zone[h][r][Z_RETURN_MIN_MS]>=s.zone[h][r][Z_RETURN_MAX_MS])return 230;',' }',' if(s.v[P_LIFT_LOW]>=s.v[P_LIFT_HIGH])return 231;',' return 0; }',
 'inline bool usableMotorPwm(uint16_t p){return p==3||p==5||p==6||p==11;}',
 'inline int pinSettingsError(const Settings &s){',
 ' uint8_t pins[16],n=0;pins[n++]=s.v[P_LEFT_IN1];pins[n++]=s.v[P_LEFT_IN2];pins[n++]=s.v[P_RIGHT_IN1];pins[n++]=s.v[P_RIGHT_IN2];',
 ' if(s.v[P_DRIVER_MODE]==0){if(!usableMotorPwm(s.v[P_LEFT_EN])||!usableMotorPwm(s.v[P_RIGHT_EN]))return 301;pins[n++]=s.v[P_LEFT_EN];pins[n++]=s.v[P_RIGHT_EN];}else{for(uint8_t i=0;i<4;i++)if(!usableMotorPwm(pins[i]))return 302;}',
 ' pins[n++]=s.v[P_SERVO_PIN];pins[n++]=s.v[P_START_PIN];pins[n++]=s.v[P_CONTACT_PIN];pins[n++]=s.v[P_LINE_LEFT];pins[n++]=s.v[P_LINE_CENTRE];pins[n++]=s.v[P_LINE_RIGHT];',
 ' if(s.v[P_LED_PIN]!=255)pins[n++]=s.v[P_LED_PIN];if(s.v[P_STANDBY_PIN]!=255)pins[n++]=s.v[P_STANDBY_PIN];',
 ' for(uint8_t i=0;i<n;i++){if(pins[i]<2||pins[i]>19)return 303;for(uint8_t j=0;j<i;j++)if(pins[i]==pins[j])return 304;}return 0;}',]
(SK/'Settings.h').write_text('\n'.join(s)+'\n',encoding='utf-8')
header=['#pragma once','#include "Settings.h"','// Values below are initial tuning values, not measurements of the physical robot.','inline void loadUserSettings(Settings &s){']
header += [f' s.v[P_{x["key"]}]={x["default"]};' for x in params]
header += [' for(uint8_t h=0;h<2;h++)for(uint8_t r=0;r<8;r++){']+[f' s.zone[h][r][Z_{x["key"]}]={x["default"]};' for x in zones]+[' }',' s.searchCount=7;for(uint8_t i=0;i<7;i++)s.search[i]=i+1;','}']
(SK/'RobotConfig.h').write_text('\n'.join(header)+'\n',encoding='utf-8')
(OUT/'settings_schema.json').write_text(json.dumps(dict(version=1,params=params,zones=zones,initialSearch=[1,2,3,4,5,6,7]),ensure_ascii=False,indent=2),encoding='utf-8')
print('Generated',len(params),'global settings and',len(zones)*16,'zone settings')
